//! Generated artifacts: JSON Schemas for every format and the reference
//! docs `events.md` and `task-document.md`. Checked in under
//! `docs/workflows/`; a test keeps them current (`ENZARB_BLESS=1 cargo test`
//! or `enzarb-lint schemas docs/workflows` rewrites them).

use crate::document::TaskDocument;
use crate::events::{Event, catalog_schemas};
use crate::format::*;
use crate::scenario::Scenario;
use schemars::schema_for;
use serde_json::Value;
use std::fmt::Write as _;

/// `(path relative to docs/workflows, contents)` of every generated file.
pub fn generated() -> Vec<(String, String)> {
    let mut out = Vec::new();
    let mut put = |name: &str, s: schemars::Schema| {
        out.push((format!("schemas/{name}.json"), pretty(&s.to_value())));
    };
    put("workflow", schema_for!(WorkflowFile));
    put("phase", schema_for!(PhaseFile));
    put("step", schema_for!(StepFile));
    put("runtime", schema_for!(RuntimeFile));
    put("board", schema_for!(BoardFile));
    put("bindings", schema_for!(BindingsFile));
    put("check", schema_for!(CheckFile));
    put("event", schema_for!(Event));
    put("task-document", schema_for!(TaskDocument));
    put("scenario", schema_for!(Scenario));
    for (name, _, s) in catalog_schemas() {
        put(&format!("events/{name}"), s);
    }
    out.push(("events.md".into(), events_md()));
    out.push(("task-document.md".into(), task_document_md()));
    out
}

fn pretty(v: &Value) -> String {
    let mut s = serde_json::to_string_pretty(v).expect("schema serializes");
    s.push('\n');
    s
}

const HEADER: &str = "<!-- Generated by `enzarb-flow` (workflows/crates/flow/src/schema.rs). Do not edit; run `ENZARB_BLESS=1 cargo test -p enzarb-flow`. -->\n\n";

fn events_md() -> String {
    let mut s = String::from(HEADER);
    s.push_str("# Event catalog\n\nThe standard event objects (ADR-0022 §5). Connectors map provider webhooks into them; waits (`events:`), steering (`steer:`), stop matchers and bindings (`on:`) match them by `type`. A custom event matches by its declared `name`. Format reference: [format.md](format.md).\n\n");
    s.push_str(
        "## Envelope\n\nEvery event has these fields next to `type` and the payload fields.\n\n",
    );
    let env = schema_for!(Event).to_value();
    table(&mut s, &env, &["type"]);
    s.push_str("\nTwo more types exist only inside the engine and can be waited on: `timer` (a wait's `timer` fired; `event.timer_id`) and `fact` (a refreshed fact; `event.fact`, `event.value`).\n");
    s.push_str("\nThe periodic `platform` source (liveness checks, [format.md](format.md#checks)) is internal: it carries no task event and never reaches the interpreter. It raises and clears findings only.\n");
    s.push_str("\nThe periodic `platform` source (liveness checks, [format.md](format.md#checks)) is internal: it carries no task event and never reaches the interpreter. It raises and clears findings only.\n");
    s.push_str("\n## Types\n");
    for (name, ty, schema) in catalog_schemas() {
        let v = schema.to_value();
        let _ = write!(s, "\n### `{name}`\n\n");
        for d in [
            payload_doc(&env, name),
            v.get("description")
                .and_then(Value::as_str)
                .map(str::to_string),
        ]
        .into_iter()
        .flatten()
        {
            let _ = writeln!(s, "{}\n", d.replace('\n', " "));
        }
        let _ = writeln!(
            s,
            "Schema: [`schemas/events/{name}.json`](schemas/events/{name}.json) (`{ty}`).\n"
        );
        table(&mut s, &v, &[]);
    }
    s
}

/// The doc comment of the `Payload` variant tagged `name`.
fn payload_doc(env: &Value, name: &str) -> Option<String> {
    let variants = env["oneOf"]
        .as_array()
        .or_else(|| env["$defs"]["Payload"]["oneOf"].as_array())?;
    variants
        .iter()
        .find(|v| v["properties"]["type"]["const"] == name)
        .and_then(|v| v["description"].as_str().map(str::to_string))
}

fn task_document_md() -> String {
    let mut s = String::from(HEADER);
    s.push_str("# Task document\n\nThe data every prompt template, `text`, action argument and condition reads (ADR-0022 §3). Templates may use these roots directly; anything else must be a declared step `input`. In conditions, `last` (the last finished step or action: `node`, `exit`, `outputs`, `result`, `git`, `missing_outputs`), `exit` (`last.exit`, or a nested phase's exit) and `params` are also defined; at waits, `event` is the candidate event. Schema: [`schemas/task-document.json`](schemas/task-document.json).\n\n## `TaskDocument`\n\n");
    let doc = schema_for!(TaskDocument).to_value();
    table(&mut s, &doc, &[]);
    if let Some(defs) = doc["$defs"].as_object() {
        for (name, d) in defs {
            if name == "Event" || name == "Payload" || d.get("properties").is_none() {
                continue;
            }
            let _ = write!(s, "\n## `{name}`\n\n");
            if let Some(desc) = d["description"].as_str() {
                let _ = writeln!(s, "{desc}\n");
            }
            table(&mut s, d, &[]);
        }
    }
    s.push_str("\n`event` is an [event](events.md) object.\n");
    s
}

fn table(s: &mut String, obj: &Value, skip: &[&str]) {
    let Some(props) = obj["properties"].as_object() else {
        s.push_str("(no fields)\n");
        return;
    };
    let required: Vec<&str> = obj["required"]
        .as_array()
        .map(|a| a.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default();
    s.push_str("| Field | Type | Required | Description |\n|---|---|---|---|\n");
    for (k, v) in props {
        if skip.contains(&k.as_str()) {
            continue;
        }
        let desc = v["description"].as_str().unwrap_or("").replace('\n', " ");
        let _ = writeln!(
            s,
            "| `{k}` | {} | {} | {desc} |",
            type_of(v),
            if required.contains(&k.as_str()) {
                "yes"
            } else {
                ""
            }
        );
    }
}

fn type_of(v: &Value) -> String {
    if let Some(r) = v["$ref"].as_str() {
        return r.rsplit('/').next().unwrap_or(r).to_string();
    }
    if let Some(any) = v["anyOf"].as_array().or_else(|| v["oneOf"].as_array()) {
        let parts: Vec<String> = any
            .iter()
            .filter(|x| x["type"] != "null")
            .map(type_of)
            .collect();
        return parts.join(" or ");
    }
    if let Some(e) = v["enum"].as_array() {
        return e
            .iter()
            .map(|x| format!("`{}`", x.as_str().unwrap_or_default()))
            .collect::<Vec<_>>()
            .join(", ");
    }
    let t = match &v["type"] {
        Value::String(t) => t.clone(),
        Value::Array(ts) => ts
            .iter()
            .filter_map(Value::as_str)
            .filter(|t| *t != "null")
            .collect::<Vec<_>>()
            .join(" or "),
        _ => "any".into(),
    };
    match t.as_str() {
        "array" => format!("list of {}", type_of(&v["items"])),
        "object" if v.get("additionalProperties").is_some_and(Value::is_object) => {
            format!("map of {}", type_of(&v["additionalProperties"]))
        }
        _ => t,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    #[test]
    fn generated_files_are_current() {
        let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../docs/workflows");
        let bless = std::env::var_os("ENZARB_BLESS").is_some();
        let mut stale = Vec::new();
        for (rel, want) in generated() {
            let p = dir.join(&rel);
            if bless {
                std::fs::create_dir_all(p.parent().unwrap()).unwrap();
                std::fs::write(&p, &want).unwrap();
            } else if std::fs::read_to_string(&p).ok().as_deref() != Some(want.as_str()) {
                stale.push(rel);
            }
        }
        assert!(
            stale.is_empty(),
            "stale generated docs (run `ENZARB_BLESS=1 cargo test -p enzarb-flow`): {stale:?}"
        );
    }
}
